import {currentQuality} from './driver-settings.js';
import {slope} from './track.js';
import * as THREE from './vendor/three.module.js';
export function createWorlds(scene,{sun,coast,terrain,asphalt,player,routeEnvironment}){
 const hemi=scene.children.find(o=>o.isHemisphereLight),originals=new Map();
 // A bounded particle pool stays near the camera; no allocations during play.
 const count=380,rainPositions=new Float32Array(count*6),snowPositions=new Float32Array(count*3);
 const rainGeo=new THREE.BufferGeometry();rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));
 const rain=new THREE.LineSegments(rainGeo,new THREE.LineBasicMaterial({color:'#c1e3f4',transparent:true,opacity:.4,depthWrite:false}));rain.frustumCulled=false;scene.add(rain);
 const snowGeo=new THREE.BufferGeometry();snowGeo.setAttribute('position',new THREE.BufferAttribute(snowPositions,3));
 const snow=new THREE.Points(snowGeo,new THREE.PointsMaterial({color:'#fffaff',size:.1,transparent:true,opacity:.9,depthWrite:false}));snow.frustumCulled=false;scene.add(snow);
 const lightTarget=new THREE.Object3D();scene.add(lightTarget);const headlight=new THREE.SpotLight('#e6f3ff',90,85,.43,.6,1.2);headlight.target=lightTarget;scene.add(headlight);
 const lights=Array.from({length:4},()=>{const l=new THREE.PointLight('#ffdf9a',22,22,1.5);scene.add(l);return l;});
 const starsGeo=new THREE.BufferGeometry(),starsP=[];for(let i=0;i<180;i++){starsP.push(Math.sin(i*137.5)*190,35+(i*17%100),-60-(i*43%170));}starsGeo.setAttribute('position',new THREE.Float32BufferAttribute(starsP,3));const stars=new THREE.Points(starsGeo,new THREE.PointsMaterial({color:'#d9ecff',size:.35}));scene.add(stars);
 const moon=new THREE.Mesh(new THREE.SphereGeometry(5,16,12),new THREE.MeshBasicMaterial({color:'#e5f0e5'}));moon.position.set(-65,72,-200);scene.add(moon);
 let current;
 function apply(id,racing,route){current=id+String(racing)+route;const city=route==='city',mountain=route==='mountain';racing=city||(racing&&!mountain);const night=id==='night',wet=id==='rain',winter=id==='snow',sky=racing?(night?'#090c20':wet?'#283448':winter?'#718298':'#252841'):night?'#081423':wet?'#607c8b':winter?'#c4d5df':'#9dcbd7';scene.background=new THREE.Color(sky);scene.fog.color.set(sky);scene.fog.far=wet?220:night?300:city?430:mountain?820:280;sun.intensity=night?.12:racing?.85:wet?.65:winter?1.25:2;hemi.intensity=night?.4:racing?.95:wet?1.05:1.6;sun.color.set(racing?'#f5c8ee':'#ffebbc');hemi.color.set(racing?'#9dcaff':'#d1eaff');scene.environmentIntensity=night?.15:racing?.33:.45;rain.visible=wet;snow.visible=winter;stars.visible=moon.visible=night;headlight.visible=night||wet||racing;lights.forEach((l,i)=>{l.visible=night||racing;l.color.set(racing?(i%2?'#ff75d9':'#78e5ff'):'#ffdf9a');});coast.bulbMaterial.emissive.set(racing?'#68eaff':'#ffd589');coast.bulbMaterial.emissiveIntensity=night||racing?3:0;
  scene.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(!originals.has(m)&&m.color)originals.set(m,{color:m.color.clone(),map:m.map});const original=originals.get(m);if(!original)continue;if(m.name==='Textured foliage'){m.color.copy(original.color);if(winter)m.color.lerp(new THREE.Color('#eef7ff'),.78);} }});
  terrain.slice(0,2).forEach(g=>g.children.forEach(m=>{const original=originals.get(m.material);m.material.map=winter?null:original.map;m.material.color.copy(original.color);if(winter)m.material.color.set('#e4edf1');m.material.needsUpdate=true;}));asphalt.roughness=wet?.22:.95;asphalt.color.set(wet?'#788995':winter?'#9caab0':'#b8bdc2');
 }
 return {update(s){const id=s.worldId||'coast';const racing=s.gameMode!=='career',route=s.routeId||'coast',lit=route==='city'||racing&&route!=='mountain';if(id+String(racing)+route!==current)apply(id,racing,route);const t=s.time||0;rainGeo.setDrawRange(0,currentQuality.name==='low'?160:count*2);snowGeo.setDrawRange(0,currentQuality.name==='low'?80:count);for(let i=0;i<(currentQuality.name==='low'?80:count);i++){const x=((i*17.37)%54)-27+s.x*.4,z=-((i*13.73+s.distance*.55)%95)+10,y=(((i*7.31-t*(id==='rain'?24:2.2))%22)+22)%22;if(id==='rain'){rainPositions.set([x,y,z,x-.15,y-.85,z+.12],i*6);}else if(id==='snow'){snowPositions.set([x+Math.sin(t+i)*.5,y,z],i*3);}}if(rain.visible)rainGeo.attributes.position.needsUpdate=true;if(snow.visible)snowGeo.attributes.position.needsUpdate=true;headlight.position.set(player.position.x,player.position.y+.7,-1.6);lightTarget.position.set(player.position.x+(s.shortcutActive?(s.shortcutActive.chordSlope-slope(s.distance,s.trackProfile))*38:0),-.1,-38);const near=(route==='coast'?coast.lamps:routeEnvironment.lamps).filter(l=>l.position.z<12&&l.position.z>-100).sort((a,b)=>b.position.z-a.position.z);lights.forEach((l,i)=>{const post=near[i];l.visible=i<currentQuality.lights&&(id==='night'||lit)&&!!post;if(post)l.position.set(post.position.x,post.position.y+5,post.position.z);});}};
}
